"""Record a user-confirmed case without rerunning the numerical engine or old plot."""
from pathlib import Path
import json,hashlib,argparse
ap=argparse.ArgumentParser();ap.add_argument('--original',default='rising-interval-review/evidence.json');ap.add_argument('--decision',default=str(Path(__file__).with_name('user-decision.json')));ap.add_argument('--out',default=str(Path(__file__).parent));a=ap.parse_args();out=Path(a.out);out.mkdir(parents=True,exist_ok=True)
src=Path(a.original);raw=src.read_bytes();sha=hashlib.sha256(raw).hexdigest();assert sha=='0349820739aa24743f28258f661bc5990255eb1a0894ca78987a60bfb41d8883';old=json.loads(raw);d=json.loads(Path(a.decision).read_text())
assert d['status']=='USER_CONFIRMED_CASE_AND_CONCEPT_DO_NOT_REASK' and d['answer_received'] is True
assert d['user_quote']=='既然你辨認的出來就可以當成一個整理區間，而且他的確是上漲中短暫回來整理後來又再度上漲'
assert all(d['confirmed_case'][k] is True for k in ['recognizable_consolidation_interval','within_rising_price_process','temporary_pullback_and_consolidation','subsequent_rise_observed'])
assert d['case']['code']=='2884' and d['case']['saved_as_of']==old['as_of']=='2026-10-16'
by={r['bar']['date']:r for r in old['recent_chart_rows']};keep=['2026-09-17','2026-10-01','2026-10-14','2026-10-15','2026-10-16'];selected=[by[k] for k in keep]
assert by['2026-09-17']['bar']['high']=='47.35' and by['2026-10-01']['bar']['low']=='44.20'
assert by['2026-10-16']['bar']['close']=='49.15' and by['2026-10-16']['bar']['high']=='49.95'
assert all(x['qualification']=='UNCONFIRMED_NOT_A_PIVOT' for x in old['current_pending_extrema'])
for k in ['primary_pressure_id','historical_selection_time','formal_price_bounds','formal_membership','lifecycle']:assert d[k] is None
assert d['historical_signal_eligible'] is False and d['action_qualification']=='NOT_EVALUATED'
e={'schema':'m1-rising-case-user-adjudication/1','qualification':'USER_CONFIRMED_QUALITATIVE_CASE_NOT_AUTOMATIC_CLASSIFIER','original_research_sha256':sha,'original_research_ref':'6c50b19303074aa1210d11051745ca0b127592e6','original_research_path':'docs/visual-discussion/20261020_rising_interval_work_review/evidence.json','original_source_data_sha256':old['source_sha256'],'original_core_sha256':old['original_core_sha256'],'original_core_result_id':old['original_core_result_id'],'price_basis_id':old['price_basis_id'],'saved_as_of':old['as_of'],'anchor':old['anchor'],'selected_original_rows':selected,'original_comparisons':old['observed_reference_comparisons'],'original_pending_extrema':old['current_pending_extrema'],'human_label_time':d['user_time'],'human_confirmed_case':d['confirmed_case'],'compatible_descriptions':{'form':'CONSOLIDATION_INTERVAL','price_process_description':'TEMPORARY_PULLBACK_AND_CONSOLIDATION_WITHIN_RISE_THEN_RISE_AGAIN','mutually_exclusive':False,'formal_lifecycle_assigned':False},'formal_price_bounds':None,'formal_membership':None,'primary_pressure_id':None,'historical_selection_time':None,'historical_signal_eligible':False}
(out/'evidence.json').write_text(json.dumps(e,ensure_ascii=False,indent=2)+'\n')
case={'schema':'m1-user-reviewed-positive-case/1','case_id':'2884-rising-pullback-consolidation-20261016','label_origin':'USER_CONFIRMED_2026-10-20T21:07:05+08:00','evidence_ref':e['original_research_ref'],'evidence_sha256':sha,'expected_qualitative_descriptions':{'consolidation_interval':True,'within_rising_process':True,'temporary_pullback_consolidation':True,'subsequent_rise':True},'descriptions_are_compatible':True,'must_preserve_original_qualifications':{'latest_high49_95':'UNCONFIRMED_NOT_A_PIVOT','exact_formal_interval_dates':None,'formal_price_bounds':None,'formal_membership':None,'primary_pressure_id':None,'historical_signal_eligible':False,'formal_lifecycle':None,'action_qualification':'NOT_EVALUATED'},'execution_status':'SAVED_REVIEWED_EVIDENCE_NOT_AN_EXECUTED_PRODUCTION_CLASSIFIER_TEST','not_production_logic':'Labels are reviewed fixture expectations, not date/price constants in an automatic recognition algorithm.'}
(out/'positive-case.json').write_text(json.dumps(case,ensure_ascii=False,indent=2)+'\n')
assert json.loads((out/'evidence.json').read_text())['selected_original_rows']==selected
assert hashlib.sha256(src.read_bytes()).hexdigest()==sha
v={'decision_quote_and_scope':'PASS_USER_MESSAGE_RECORDED','positive_case_form_and_direction_both_true':'PASS_USER_CONFIRMED_NOT_AUTOMATIC_INFERENCE','original_research_exact_current_GitHub_text':'PASS_READBACK_BEFORE_AUDIT','original_research_SHA_unchanged':sha,'five_selected_original_OHLCV_MA_MACD_rows_exact':'PASS_COPIED_NOT_RECALCULATED','original_reference_comparisons_and_pending_extrema_unchanged':'PASS','formal_dates_bounds_membership_lifecycle_primary_unknown':'PASS_NOT_FILLED','historical_signal_eligible':False,'new_execution':'RESEARCH_DECISION_AUDIT_ONLY','existing_reaction_adapter_for_2884':'README_CONTRACT_INSPECTED_NOT_EXECUTED_OR_VERIFIED','core_MACD_reaction_query_adapter_CLI_bootstrap_old_tests':'NOT_RUN','new_PDF_or_chart':'NOT_CREATED_OLD_ARTIFACTS_UNCHANGED','old_static_PDF_QA':'HISTORICAL_PASS_NOT_RERUN','ZIP_browser':'NOT_RUN','Android':'NOT_TESTED_NEW_BUILD'}
(out/'verification.json').write_text(json.dumps(v,ensure_ascii=False,indent=2)+'\n');print(json.dumps({'decision':'USER_CONFIRMED','compatible_descriptions':True,'original_rows_copied':len(selected),'old_source_SHA_unchanged':True,'automatic_classifier':'NOT_IMPLEMENTED_OR_VALIDATED'}))
